//! Generation of the module registry the library includes, and the content
//! hash that keeps it from going stale.
//!
//! Pure string work plus one file write, so an integration test can generate a
//! registry and read it back without a compiler anywhere on the machine.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

/// The first line of the generated file.
///
/// It is a literal, checked by the tests and by the manual Linux runbook, which
/// is how a build that produced a real registry is told apart from one that
/// produced a stub: the file exists either way, and only its contents differ.
pub(crate) const HEADER: &str = "// Auto-generated by build.rs — do not edit.";

/// Lowercase accessor name, which is also the artefact kind.
const ACCESSOR: &str = "ptx";

/// Uppercase constant suffix.
const SUFFIX: &str = "PTX";

/// The file the registry is written to inside `OUT_DIR`.
const FILE_NAME: &str = "target_ptx.rs";

/// Generate the registry's source text.
///
/// Entries are `(module name, absolute artefact path)`. An empty slice produces
/// a registry with no modules and the same accessors, which is what every build
/// on a machine without a device compiler gets: the crate still type-checks,
/// every caller still compiles, and every lookup answers with an empty slice
/// that the loader refuses rather than a panic that takes the process down.
pub(crate) fn generate_registry(entries: &[(String, PathBuf)]) -> String {
    let accessor = ACCESSOR;
    let suffix = SUFFIX;
    let table = format!("{suffix}_MODULES");
    let mut g = String::new();
    let ok = "writing to a String cannot fail";
    writeln!(g, "{HEADER}").expect(ok);
    writeln!(
        g,
        "// {} module(s); artefact paths are resolved against SHISO_KERNELS_OUT_DIR.\n",
        entries.len()
    )
    .expect(ok);

    for (module, path) in entries {
        writeln!(
            g,
            "const {}_{suffix}: &[u8] = include_bytes!({:?});",
            const_ident(module),
            path.display().to_string(),
        )
        .expect(ok);
    }
    if !entries.is_empty() {
        g.push('\n');
    }

    writeln!(
        g,
        "/// Every `{accessor}` module in this build, as `(module name, bytes)`.\n\
         static {table}: &[(&str, &[u8])] = &["
    )
    .expect(ok);
    for (module, _) in entries {
        writeln!(g, "    ({module:?}, {}_{suffix}),", const_ident(module)).expect(ok);
    }
    g.push_str("];\n\n");

    writeln!(
        g,
        "/// Bytes of the `{accessor}` module named `module`.\n\
         ///\n\
         /// An unknown name answers with an empty slice. That is deliberate: the name\n\
         /// came from a registry generated at build time, so an unknown one means the\n\
         /// binary was built without that kernel, which a debug build should catch at\n\
         /// once and a release build must survive. Zero bytes fail the module load\n\
         /// that follows, so the error surfaces there with the device's own message\n\
         /// instead of taking the process down here.\n\
         #[must_use]\n\
         pub fn {accessor}(module: &str) -> &'static [u8] {{\n\
         \x20   let found = {table}.iter().find(|&&(name, _)| name == module);\n\
         \x20   debug_assert!(found.is_some(), \"unknown kernel module: {{module}}\");\n\
         \x20   found.map_or(&[], |&(_, bytes)| bytes)\n\
         }}\n\n\
         /// Every `{accessor}` module in this build, for registry audits.\n\
         #[must_use]\n\
         pub fn {accessor}_modules() -> Vec<(&'static str, &'static [u8])> {{\n\
         \x20   {table}.to_vec()\n\
         }}"
    )
    .expect(ok);
    g
}

/// A module name turned into a Rust constant identifier.
fn const_ident(module: &str) -> String {
    let mut ident: String = module
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_uppercase()
            } else {
                '_'
            }
        })
        .collect();
    if ident.starts_with(|c: char| c.is_ascii_digit()) {
        ident.insert(0, '_');
    }
    ident
}

/// Write the registry into `out_dir` and return its text.
///
/// The file is always written, even when nothing was compiled. The library
/// includes it unconditionally, so a build that emitted nothing would fail to
/// compile on a missing `include!` — an error about a path in a temporary
/// directory, which says nothing about the actual cause.
pub(crate) fn write_registry(
    out_dir: &Path,
    entries: &[(String, PathBuf)],
) -> Result<String, String> {
    let generated = generate_registry(entries);
    let path = out_dir.join(FILE_NAME);
    std::fs::write(&path, &generated)
        .map_err(|e| format!("cannot write {}: {e}", path.display()))?;
    Ok(generated)
}

/// Write an empty registry — the path every build without a device compiler
/// takes — and return its text.
pub(crate) fn write_stub_registry(out_dir: &Path) -> Result<String, String> {
    write_registry(out_dir, &[])
}

/// A 64-bit FNV-1a fingerprint of `s`, as 12 hex characters.
///
/// This exists to close a hole cargo cannot see: the library pulls its registry
/// in with `include!` of a file the build script wrote, and cargo does not track
/// build-script output as a recompile trigger. Without the fingerprint a binary
/// can keep an embedded module list from a previous kernel set indefinitely.
/// Surfacing the hash as a `rustc-env` the library references with `env!` makes
/// a changed registry change the crate's own fingerprint, which forces the
/// rebuild. The function is deliberately dependency-free and deterministic —
/// a hash that varied between runs would rebuild the crate every time.
pub(crate) fn content_hash(s: &str) -> String {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in s.as_bytes() {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    format!("{:012x}", h & 0xffff_ffff_ffff)
}
